const fs=require('fs'),path=require('path'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/components/cards/professional-showcase-card.css';
const HOME_CSS='assets/css/pages/home.css';
const RESULTS_CSS='assets/css/pages/search-results.css';
const HOME_PAGE='index.html';
const RESULTS_PAGE='resultados.html';
const SEL='body.home-index-shell .professional-showcase > .professional-showcase__rail > .professional-showcase__track';
const VIEWPORTS=[359,389,390,391,430,759,760,761,1024];
const SHA=process.env.TARGET_SHA,TARGET_BLOB=process.env.TARGET_BLOB,HOME_CSS_BLOB=process.env.HOME_CSS_BLOB,RESULTS_CSS_BLOB=process.env.RESULTS_CSS_BLOB,HOME_PAGE_BLOB=process.env.HOME_PAGE_BLOB,RESULTS_PAGE_BLOB=process.env.RESULTS_PAGE_BLOB;
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v)}return out}
function verifyStatic(){assert(SHA&&TARGET_BLOB&&HOME_CSS_BLOB&&RESULTS_CSS_BLOB&&HOME_PAGE_BLOB&&RESULTS_PAGE_BLOB,'missing env');assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');for(const [f,b] of [[TARGET,TARGET_BLOB],[HOME_CSS,HOME_CSS_BLOB],[RESULTS_CSS,RESULTS_CSS_BLOB],[HOME_PAGE,HOME_PAGE_BLOB],[RESULTS_PAGE,RESULTS_PAGE_BLOB]])assert(sh(`git hash-object ${f}`)===b,`blob drift ${f}`);const home=fs.readFileSync(HOME_PAGE,'utf8'),results=fs.readFileSync(RESULTS_PAGE,'utf8');assert(home.includes('class="professional-showcase doke-page-section"')&&home.includes('class="professional-showcase__track"'),'home static showcase emitter missing');assert(/<body[^>]*class="[^"]*home-index-shell/.test(home),'home scope class missing');assert(!/<body[^>]*class="[^"]*home-index-shell/.test(results),'results unexpectedly has home-index-shell');const tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css'))),direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)===JSON.stringify([HOME_CSS,RESULTS_CSS].sort()),`direct importer drift ${JSON.stringify(direct)}`);const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),reached=[];for(const p of report.pageAssets){const seen=new Set(),todo=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(todo.length){const f=todo.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break}for(const n of importsFor(f,tracked))todo.push(n)}if(hit)reached.push(p.page)}reached.sort();assert(JSON.stringify(reached)===JSON.stringify([HOME_PAGE,RESULTS_PAGE].sort()),`active reach drift ${JSON.stringify(reached)}`);console.log(`R1 REACH PASS|target=${TARGET}|directImporters=${direct.join(',')}|activeReach=${reached.join(',')}|homeEmitter=static-real|resultsTargetScopeMatch=0`)}
function verifyDead(){const p=parse(fs.readFileSync(TARGET,'utf8'));assert(p.declarations.length===214&&p.dead.length===1,`target parse drift ${p.declarations.length}/${p.dead.length}`);const d=p.dead[0];assert(d.line===323&&d.selector===SEL&&d.property==='gap'&&d.value==='14px'&&!d.important,'dead row drift');assert(d.context.includes('@media (max-width: 760px)'),'dead context drift');assert(d.winnerLine===366&&d.winnerValue==='var(--professional-showcase-gap)'&&!d.winnerImportant,'winner drift');console.log('R1 CASCADE PASS|decl=214|dead=1|family=1|line=323|prop=gap|value=14px|context=max760|winnerLine=366|winnerValue=var(--professional-showcase-gap)|changed=1');return p}
function removeDead(p){const d=p.dead[0],src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();assert(lines[d.line-1]?.trim()==='gap: 14px;',`source line drift ${d.line}: ${lines[d.line-1]}`);lines.splice(d.line-1,1);fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(after.declarations.length===213&&after.dead.length===0,`after parse drift ${after.declarations.length}/${after.dead.length}`);assert(stat[0]==='0'&&stat[1]==='1'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);console.log('R1 REMOVE PASS|decl=214->213|dead=1->0|additions=0|deletions=1')}
async function prepHome(page){await page.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');const s=document.querySelector('.professional-showcase');if(!s)throw new Error('showcase section missing');s.hidden=false;const freeze=document.createElement('style');freeze.textContent='*,*::before,*::after{transition-duration:0s!important;transition-delay:0s!important;animation-duration:0s!important;animation-delay:0s!important}';document.head.appendChild(freeze)});await page.waitForFunction(sel=>{const el=document.querySelector(sel);return !!el&&getComputedStyle(el).display!=='none'},SEL,{timeout:5000})}
async function snapHome(page,width){return page.evaluate(({SEL,width})=>{const track=document.querySelector(SEL),section=document.querySelector('.professional-showcase'),rail=document.querySelector('.professional-showcase__rail'),cards=[...track.children].slice(0,4);if(!track||!section||!rail||cards.length<4)throw new Error('real showcase anatomy missing');const cs=getComputedStyle(track),round=n=>Math.round(n*1000)/1000,rect=e=>{const r=e.getBoundingClientRect();return[round(r.x),round(r.y),round(r.width),round(r.height)]};return{width,matches:document.querySelectorAll(SEL).length,track:{display:cs.display,gap:cs.gap,rowGap:cs.rowGap,columnGap:cs.columnGap,overflowX:cs.overflowX,overflowY:cs.overflowY,rect:rect(track),clientWidth:track.clientWidth,scrollWidth:track.scrollWidth},rail:{rect:rect(rail),clientWidth:rail.clientWidth,scrollWidth:rail.scrollWidth},section:rect(section),cards:cards.map(rect),doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]};},{SEL,width})}
async function snapResults(page,width){return page.evaluate(({SEL,width})=>({width,matches:document.querySelectorAll(SEL).length,homeScope:document.body.classList.contains('home-index-shell'),doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]}),{SEL,width})}
async function capture(browser,tag){const home={},results={};let homeOverflow=0,resultsOverflow=0;for(const width of VIEWPORTS){for(const kind of ['home','results']){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(!local)return route.abort();if(u.pathname.endsWith('.js'))return route.abort();return route.continue()});const file=kind==='home'?HOME_PAGE:RESULTS_PAGE;await page.goto(`http://127.0.0.1:4173/${file}?ux053-r1-${tag}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});if(kind==='home'){await prepHome(page);const s=await snapHome(page,width);assert(s.matches===1,`home selector match drift ${width}/${s.matches}`);if(width===759||width===760)assert(s.track.gap==='12px',`winner not effective at ${width}: ${s.track.gap}`);if(s.doc[1]>s.doc[0]+1||s.doc[2]>s.doc[0]+1)homeOverflow++;home[String(width)]=s}else{const s=await snapResults(page,width);assert(s.matches===0&&!s.homeScope,`results negative scope drift ${width}`);if(s.doc[1]>s.doc[0]+1||s.doc[2]>s.doc[0]+1)resultsOverflow++;results[String(width)]=s}await ctx.close()}}console.log(`R1 BROWSER CAPTURE|tag=${tag}|homeSamples=${VIEWPORTS.length}|resultsNegativeSamples=${VIEWPORTS.length}|viewports=${VIEWPORTS.join(',')}|homeOverflow=${homeOverflow}|resultsOverflow=${resultsOverflow}`);return{home,results,homeOverflow,resultsOverflow}}
(async()=>{verifyStatic();const parsed=verifyDead();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(before.homeOverflow===after.homeOverflow&&before.resultsOverflow===after.resultsOverflow,`overflow parity drift home ${before.homeOverflow}/${after.homeOverflow} results ${before.resultsOverflow}/${after.resultsOverflow}`);assert(JSON.stringify(before.home)===JSON.stringify(after.home),'home computed/layout parity drift');assert(JSON.stringify(before.results)===JSON.stringify(after.results),'results negative-scope parity drift');console.log(`R1 PARITY PASS|homeRuntimeDiffs=0|resultsScopeDiffs=0|overflowParity=${before.homeOverflow}->${after.homeOverflow}/${before.resultsOverflow}->${after.resultsOverflow}|critical=389/390/391+759/760/761|winnerAt759And760=12px`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
